const socket=io(),$=s=>document.querySelector(s),esc=v=>{const e=document.createElement('div');e.textContent=v||'';return e.innerHTML};let me,chats=[],activeChat,messages=[],file,typingTimer,recorder,chunks=[];const colors=['amber','violet','sky','rose'];
const avatar=(u,s='')=>`<div class="avatar avatar-${colors[(u?.name||'?').charCodeAt(0)%4]} ${s}">${esc((u?.name||'?')[0])}</div>`;const toast=t=>{const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2300)};const current=()=>chats.find(c=>c.id===activeChat);const time=x=>new Date(x).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
function profile(){$('#profileName').textContent=me?.name||'Not connected';$('#profileInitial').textContent=me?.name?.[0]||'?';$('#profileStatus').textContent=me?'@'+me.username:'Sign in to connect';$('#settingsName').value=me?.name||'';$('#settingsAvatar').value=me?.avatar||'';$('#settingsEmail').value=me?.email||''}
function chatList(){let q=$('#search').value.toLowerCase();$('#conversationList').innerHTML=chats.filter(c=>(c.title+(c.last?.text||'')).toLowerCase().includes(q)).map(c=>`<button class="conversation ${c.id===activeChat?'active':''}" data-id="${c.id}">${avatar(c.type==='group'?{name:c.title}:c.members.find(x=>x.username!==me.username))}<span><strong>${esc(c.title)} ${c.type==='group'?'<em>GROUP</em>':''}</strong><p>${esc(c.last?.text||'No messages yet')}</p></span><time>${c.last?time(c.last.at):''}</time></button>`).join('')||'<p class="empty">No conversations yet.</p>';document.querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>choose(x.dataset.id))}
function header(){let c=current();$('#chatTitle').textContent=c?c.title:'Welcome to M-Connect';$('#headerAvatar').textContent=c?.type==='group'?'#':c?.title?.[0]||'#';$('#chatPresence').textContent=c?`${c.members.filter(x=>x.online).length} online · ${c.members.length} member${c.members.length===1?'':'s'}${c.type==='group'?' · code '+c.id:''}`:'Select or create a conversation';$('#messageInput').disabled=!c;$('#videoCallButton').disabled=!c||c.members.length!==2}
function attachment(a){if(!a)return'';if(a.type.startsWith('image/'))return`<a href="${a.data}" target="_blank"><img class="message-image" src="${a.data}"></a>`;if(a.type.startsWith('audio/'))return`<audio controls src="${a.data}"></audio>`;return`<a class="file-link" href="${a.data}" download="${esc(a.name)}">↧ ${esc(a.name||'Download attachment')}</a>`}
function showMessages(){let a=$('#messageArea'),c=current();if(!c){a.innerHTML='<div class="empty-state"><h2>Your messages, organized.</h2><p>Create a private conversation or group to get started.</p></div>';return}let html=`<p class="day-marker">${c.type==='group'?'GROUP CHAT':'DIRECT MESSAGE'}</p>`;for(const m of messages){let own=m.sender===me.username,u=c.members.find(x=>x.username===m.sender)||{name:m.sender};let rs=Object.entries(m.reactions||{}).map(([e,p])=>`<button class="reaction" data-r="${m.id}" data-e="${esc(e)}">${esc(e)} ${p.length}</button>`).join('');let body=m.deleted?'<i>Message deleted</i>':`${own?'':`<b>${esc(u.name)}</b><br>`}${esc(m.text).replace(/\n/g,'<br>')}${attachment(m.attachment)}`;let actions=m.deleted?'':`<div class="message-actions"><button data-r="${m.id}" data-e="👍">☺</button>${own?`<button data-edit="${m.id}">Edit</button><button data-del="${m.id}">Delete</button>`:''}</div><div class="reactions">${rs}</div>`;html+=`<article class="message ${own?'me':'them'}">${avatar(u,'small')}<div class="message-stack"><div class="bubble">${body}<time class="time">${time(m.at)}${m.editedAt?' · edited':''}</time></div>${actions}</div></article>`}a.innerHTML=html;a.scrollTop=a.scrollHeight;document.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>socket.emit('react-message',{chatId:activeChat,messageId:b.dataset.r,emoji:b.dataset.e}));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>socket.emit('delete-message',{chatId:activeChat,messageId:b.dataset.del}));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{let m=messages.find(x=>x.id===b.dataset.edit),text=prompt('Edit message',m.text);if(text!==null)socket.emit('edit-message',{chatId:activeChat,messageId:m.id,text})})}
function choose(id){activeChat=id;messages=[];chatList();header();showMessages();socket.emit('load-messages',id,r=>{if(!r.ok)return toast(r.error);if(activeChat===id){messages=r.messages;current().members=r.members;header();showMessages()}});$('#sidebar').classList.remove('open')}
function merge(c){let i=chats.findIndex(x=>x.id===c.id);if(i<0)chats.unshift(c);else chats[i]={...chats[i],...c};chats.sort((a,b)=>(b.last?.at||'').localeCompare(a.last?.at||''));chatList();header()}
function send(attachment){if(!activeChat)return;let text=$('#messageInput').value.trim();if(!text&&!file&&!attachment)return;let done=r=>{if(!r.ok)return toast(r.error);messages.push(r.message);$('#messageInput').value='';file=null;$('#fileInput').value='';$('#messageInput').placeholder='Write a message…';showMessages();socket.emit('stop-typing',activeChat)};if(file){let rd=new FileReader();rd.onload=()=>socket.emit('send-message',{chatId:activeChat,text,attachment:{name:file.name,type:file.type,data:rd.result}},done);rd.readAsDataURL(file)}else socket.emit('send-message',{chatId:activeChat,text,attachment},done)}
$('#composer').onsubmit=e=>{e.preventDefault();send()};$('#messageInput').oninput=()=>{if(activeChat){socket.emit('typing',activeChat);clearTimeout(typingTimer);typingTimer=setTimeout(()=>socket.emit('stop-typing',activeChat),900)}};$('#fileInput').onchange=e=>{file=e.target.files[0];if(file?.size>2*1024*1024){file=null;return toast('Files must be smaller than 2 MB.')};if(file)$('#messageInput').placeholder='Ready to send: '+file.name};$('#emojiButton').onclick=()=>{$('#messageInput').value+=' 😊';$('#messageInput').focus()};$('#search').oninput=chatList;$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');
$('#newChat').onclick=()=>$('#newChatDialog').showModal();$('#addContact').onclick=()=>{let u=prompt('Friend username');if(u)socket.emit('add-contact',u,r=>toast(r.ok?`${r.contact.name} added.`:r.error))};$('#newChatForm').onclick=e=>{let b=e.target.closest('button[name=action]');if(!b)return;e.preventDefault();let event,payload;if(b.value==='direct'){event='open-direct';payload=$('#directUser').value}else if(b.value==='group'){event='create-group';payload={title:$('#groupName').value,members:$('#groupMembers').value.split(','),password:$('#groupPassword').value}}else{event='join-group';payload={code:$('#joinCode').value,password:$('#joinPassword').value}}socket.emit(event,payload,r=>{if(!r.ok)return toast(r.error);merge(r.chat);$('#newChatDialog').close();choose(r.chat.id);toast(b.value==='group'?`Group created. Code: ${r.chat.id}`:'Conversation ready.')})};
const authError=message=>{let element=$('#authError');if(!element){element=document.createElement('p');element.id='authError';element.setAttribute('role','alert');Object.assign(element.style,{margin:'2px 0 12px',padding:'9px 11px',border:'1px solid #9c5555',borderRadius:'8px',background:'#3a2020',color:'#ffd7d1',fontSize:'12px',lineHeight:'1.35'});$('#authSubmit').before(element)}element.textContent=message||'';element.hidden=!message};
let login=true;
function authMode(){authError('');$('#authTitle').textContent=login?'Welcome back.':'Your conversations, yours to keep.';$('#authSubmit').textContent=login?'Sign in':'Create account';$('#authSwitch').textContent=login?'New here? Create an account':'Already have an account? Sign in';$('#nameLabel').hidden=login;$('#emailLabel').hidden=login}
authMode();
$('#authSwitch').onclick=()=>{login=!login;authMode()};
$('#authForm').oninput=()=>authError('');
$('#authForm').onsubmit=e=>{e.preventDefault();authError('');socket.emit(login?'auth-login':'auth-register',{name:$('#nameInput').value,email:$('#emailInput').value,username:$('#usernameInput').value,password:$('#passwordInput').value},r=>{if(!r.ok){authError(r.error);return}localStorage.setItem('m-connect-token',r.token);socket.emit('auth-session',r.token)})};
$('#settingsButton').onclick=()=>me&&$('#settingsDialog').showModal();
$('#settingsForm').onsubmit=e=>{e.preventDefault();socket.emit('update-profile',{name:$('#settingsName').value,email:$('#settingsEmail').value,avatar:$('#settingsAvatar').value},r=>{if(r.ok){me=r.me;profile();$('#settingsDialog').close()}else toast(r.error)})};
$('#logoutButton').onclick=()=>{localStorage.removeItem('m-connect-token');socket.emit('logout');location.reload()};
$('#voiceButton').onclick=async()=>{if(recorder)return recorder.stop();try{let stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());let blob=new Blob(chunks,{type:recorder.mimeType}),rd=new FileReader();if(blob.size>2*1024*1024)return toast('Voice note is too large.');rd.onload=()=>{file=null;socket.emit('send-message',{chatId:activeChat,text:'',attachment:{name:'voice-message.webm',type:blob.type,data:rd.result}},r=>{if(r.ok){messages.push(r.message);showMessages()}else toast(r.error)})};rd.readAsDataURL(blob);recorder=null;$('#voiceButton').classList.remove('recording')};recorder.start();$('#voiceButton').classList.add('recording');toast('Recording… tap again to send.')}catch{toast('Microphone access was not granted.')}};
socket.on('bootstrap',d=>{me=d.me;chats=d.chats;profile();chatList();header();$('#authDialog').close();if(chats[0])choose(chats[0].id)});socket.on('chat-updated',merge);socket.on('message-new',d=>{if(d.chatId===activeChat){messages.push(d.message);showMessages()}if(document.hidden&&d.message.sender!==me?.username&&Notification.permission==='granted')new Notification('M-Connect',{body:d.message.text||'New attachment'})});socket.on('message-update',d=>{if(d.chatId===activeChat){let i=messages.findIndex(x=>x.id===d.message.id);if(i>=0){messages[i]=d.message;showMessages()}}});socket.on('typing',d=>{if(d.chatId===activeChat){$('#typing').textContent=d.name?`${d.name} is typing…`:'';$('#typing').classList.toggle('show',!!d.name)}});socket.on('presence',u=>{chats.forEach(c=>{let m=c.members.find(x=>x.username===u.username);if(m)Object.assign(m,u)});chatList();header()});socket.on('connect',()=>{let t=localStorage.getItem('m-connect-token');if(t)socket.emit('auth-session',t,r=>{if(!r.ok)$('#authDialog').showModal()});else $('#authDialog').showModal()});if('Notification'in window&&Notification.permission==='default')Notification.requestPermission();

/* Usability upgrades: onboarding, upload feedback, recording feedback, and unread badges. */
let unreadCounts=JSON.parse(localStorage.getItem('m-connect-unread')||'{}'),voiceTimer;
const saveUnread=()=>localStorage.setItem('m-connect-unread',JSON.stringify(unreadCounts));
const originalChatList=chatList;
chatList=function(){originalChatList();for(const [chatId,count] of Object.entries(unreadCounts)){const row=document.querySelector(`[data-id="${chatId}"]`);if(row&&count){let badge=document.createElement('b');badge.className='unread-badge';badge.textContent=count>99?'99+':count;row.append(badge)}}};
const originalShowMessages=showMessages;
showMessages=function(){originalShowMessages();if(!activeChat){const state=document.querySelector('.empty-state');if(state){state.insertAdjacentHTML('beforeend','<button type="button" class="empty-action" id="startChatAction">Start a conversation</button>');$('#startChatAction').onclick=()=>$('#newChatDialog').showModal()}return}};
function setAttachmentStatus(selected){let status=$('#attachmentStatus');if(!status){status=document.createElement('div');status.id='attachmentStatus';status.className='attachment-status';$('#composer').before(status)}if(!selected){status.hidden=true;status.textContent='';return}status.hidden=false;status.innerHTML=`<span>Ready: ${esc(selected.name)} · ${Math.ceil(selected.size/1024)} KB</span><button type="button" id="removeAttachment" aria-label="Remove attachment">×</button>`;$('#removeAttachment').onclick=()=>{file=null;$('#fileInput').value='';$('#messageInput').placeholder='Write a message…';setAttachmentStatus(null)}}
$('#fileInput').addEventListener('change',()=>file&&setAttachmentStatus(file));
$('#voiceButton').addEventListener('click',()=>{if(recorder){clearInterval(voiceTimer);setTimeout(()=>{$('#voiceButton').querySelector('span').textContent='Voice'},0);return}let started=Date.now();voiceTimer=setInterval(()=>{let elapsed=Math.floor((Date.now()-started)/1000),label=$('#voiceButton').querySelector('span');if(label)label.textContent=`${Math.floor(elapsed/60)}:${String(elapsed%60).padStart(2,'0')}`},1000)},true);
socket.on('message-new',data=>{if(data.chatId!==activeChat){unreadCounts[data.chatId]=(unreadCounts[data.chatId]||0)+1;saveUnread();chatList()}});
const originalChoose=choose;
choose=function(id){unreadCounts[id]=0;saveUnread();originalChoose(id)};

const resetToken=new URLSearchParams(location.search).get('reset');
$('#forgotPassword').onclick=()=>{ $('#authDialog').close();$('#forgotDialog').showModal() };
$('#forgotBack').onclick=()=>{$('#forgotDialog').close();$('#authDialog').showModal()};
$('#forgotForm').onsubmit=e=>{e.preventDefault();socket.emit('request-password-reset',{email:$('#forgotEmail').value},reply=>{if(!reply.ok)return toast(reply.error);toast(reply.message);$('#forgotDialog').close();$('#authDialog').showModal()})};
$('#resetForm').onsubmit=e=>{e.preventDefault();const password=$('#resetPassword').value;if(password!==$('#resetPasswordConfirm').value)return toast('Passwords do not match.');socket.emit('reset-password',{token:resetToken,password},reply=>{if(!reply.ok)return toast(reply.error);history.replaceState({},'',location.pathname);$('#resetDialog').close();login=true;authMode();$('#authDialog').showModal();toast('Password updated. Please sign in.')})};
if(resetToken){$('#authDialog').close();$('#resetDialog').showModal()}

if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(error=>console.warn('PWA offline support was not installed:',error)));

const sidebarClose=document.createElement('button');
sidebarClose.type='button';sidebarClose.className='sidebar-close';sidebarClose.setAttribute('aria-label','Close conversations menu');sidebarClose.title='Close menu';sidebarClose.textContent='×';
$('#sidebar').prepend(sidebarClose);sidebarClose.onclick=()=>$('#sidebar').classList.remove('open');
$('#addContact').innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="3"></circle><path d="M3 20c.5-4 2.5-6 6-6 1.5 0 2.7.3 3.7 1M19 8v6M16 11h6"></path></svg>';
$('#addContact').setAttribute('aria-label','Add user');$('#addContact').title='Add user';
